import useCompanyVirtualCard from '@apps/borrower/hooks/useCompanyVirtualCard';
import Loading from '@components/Loading';
import React, { useEffect, useState } from 'react';
import AddToDigitalWalletInstructions from '../AddToDigitalWalletInstructions';
import { qoloWidgetOrigin } from '@lib/constants/SiteVariables';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCheckCircle } from '@fortawesome/pro-regular-svg-icons';

declare const window: any;

export default function MultiUseVirtualCardDetails() {
  const { virtualCard, refetchVirtualCard, virtualCardRefetching } = useCompanyVirtualCard();
  const [status, setStatus] = useState('');

  const widget = {
    onSuccess: () => {
      setStatus('Card details will be masked after 90 seconds');
    },
    onFailure: () => {
      setStatus('Failed to retrieve card details');
    },
    frame: {
      container_id: 'widget_container',
      iframe_class: 'widget-iframe min-h-[276px] md:min-h-[338px] w-full mx-auto overflow-y-scroll border-0',
      //loading spinner
      // src: 'https://raw.githubusercontent.com/n3r4zzurr0/svg-spinners/main/preview/eclipse-black-36.svg',
      spinner: true,
      display: 'flex',
      filter: 'invert(27%) sepia(51%) saturate(2878%) hue-rotate(346deg) brightness(104%)',
      version: 'v3',
    },
    target_origin: qoloWidgetOrigin(),
    config: {
      token: virtualCard?.pci_token,
      copy_to_clipboard: true,
      main: 'show_pan',
      timeout: 90,
      auto_submit: true,
      css: {
        container: {
          border: 0,
        },
        'div#show_pan .row:has(div):has(h1):has(span#show_pan_head)': {
          display: 'none',
        },
        'div#submit .row:has(div):has(span#status)': {
          display: 'none',
        },
        vc_bg: {
          background: 'url(data:image/png;base64,)',
          'background-size': 'contain',
        },
        vc_number: {
          color: '#fff',
          top: '70%',
          'font-size': '4.0vw',
        },
        card_exp_date: {
          color: '#fff',
          top: '10%',
          'font-size': '3.4vw',
        },
        card_cvv: {
          color: '#fff',
          top: '10%',
          'font-size': '3.4vw',
        },
        copy_clipboard_success: {
          display: 'block',
        },
      },
      content: {
        copy_clipboard_text: 'Copy card number',
        // vc_name: `${entity?.borrower?.first_name}`,
      },
      remove: {
        copy_clipboard: 'w-100',
        row: 'my-4',
        'col-4': 'col-4',
      },
      add: {
        row: 'my-2',
      },
    },
  };

  useEffect(() => {
    refetchVirtualCard();
  }, []);

  useEffect(() => {
    if (!virtualCardRefetching && virtualCard?.pci_token) {
      widget.config.token = virtualCard.pci_token;
      window.pciWidget(widget);
    }
  }, [virtualCard]);

  return (
    <>
      <div className="bg-background-success/60 text-success p-3 rounded-lg">
        <FontAwesomeIcon icon={faCheckCircle} className="text-success/80 mr-2" />
        Success! Your card is ready to use
      </div>
      <div id='widget_container'>
        {virtualCardRefetching && <Loading className="w-14 h-14 my-20 !text-primary" />}
      </div>
      <p className="m-4 mb-0 bg-gray-50 p-4 rounded-lg">{status}</p>
      {virtualCard?.pci_token && (
        <div className="mt-4 border-t border-gray-100">
          <AddToDigitalWalletInstructions />
        </div>
      )}
    </>
  );
};

